examples.code:
MonarchCookieConsentBanner(
    policyURL: URL(string: "https://example.com/cookie-policy"),
    onCustomize: { showsChoices = true }
) { decision in
    choice = decision
}
.sheet(isPresented: $showsChoices) {
    ScrollView {
        MonarchConsentPreferences(
            categories: [
                MonarchConsentPreferencesCategory(id: "necessary", label: "Strictly necessary", description: "Keep the site working.", isRequired: true),
                MonarchConsentPreferencesCategory(id: "analytics", label: "Analytics", description: "Measure use."),
            ],
            policyURL: URL(string: "https://example.com/cookie-policy")
        ) { _, _ in
            showsChoices = false
        }
        .padding()
    }
}

MonarchCookieConsentBanner(
    regime: .optOut,
    policyURL: URL(string: "https://example.com/cookie-policy"),
    labels: MonarchCookieConsentBannerLabels(title: "Your privacy choices")
) { _ in }

MonarchCookieConsentBanner(
    regime: .notice,
    policyURL: URL(string: "https://example.com/cookie-policy"),
    labels: MonarchCookieConsentBannerLabels(title: "About cookies")
) { _ in }
